window.mountPhones = function (root) {
  (root || document).querySelectorAll('[data-screen]:not([data-mounted])').forEach(function (el) {
    var s = window.SELFLABS_SCREENS.find(function (x) { return x.id === el.dataset.screen; });
    if (!s) return;
    el.dataset.mounted = '1';
    el.innerHTML = '<div class="phone' + (s.dark ? ' dark' : '') + '"><div class="phone-screen">' + s.html + '</div><i class="phone-island"></i></div>';
  });
};
